Implement nonce validation:

Option 1: Bitmap-based (allows out-of-order execution)
mapping(address => mapping(uint256 => bool)) public usedNonces;

function openFor(...) external {
require(!usedNonces[order.user][order.nonce], "Nonce already used");
usedNonces[order.user][order.nonce] = true;
// ... rest of logic
}

Option 2: Sequential (enforces order)
mapping(address => uint256) public userNonces;

function openFor(...) external {
require(order.nonce == userNonces[order.user], "Invalid nonce");
userNonces[order.user]++;
// ... rest of logic
}

Option 3: Permit2 (handles nonces internally)
PERMIT2.permitWitnessTransferFrom(permit, details, user, witness, witnessType, signature);

Validate output amounts match minReceived:

function fill(...) external {
ResolvedCrossChainOrder memory order = abi.decode(...);

// Process fill instructions
for (uint256 i = 0; i < order.fillInstructions.length; i++) {
FillInstruction memory instruction = order.fillInstructions[i];

if (instruction.destinationChainId == block.chainid) {
// Validate each output
for (uint256 j = 0; j < instruction.outputs.length; j++) {
Output memory output = instruction.outputs[j];
Output memory minOutput = order.minReceived[j];

// CRITICAL: Validate amount meets minimum
require(
output.amount >= minOutput.amount,
"Output below minimum"
);

// Transfer tokens
_transfer(output.token, output.recipient, output.amount);
}
}
}
}

